  (6, 5, '성동 셔틀콕 모임', '성동구 배드민턴 생활체육 동호회입니다.', 12, '모집중', NULL, '3,6', '19:00:00', '21:00:00', NULL, '2025-08-03 10:00:00'),
  (7, 5, '광진 배드민턴회', '광진구 주민 중심의 배드민턴 동호회입니다.', 10, '마감', NULL, '2,5', '20:00:00', '22:00:00', NULL, '2025-08-24 10:00:00'),
